/** Security-relevant notification mutations require a committed audit, not best-effort logging. */
function notification_audit(int $actor,string $action,string $detail):void {
    if(!db()->inTransaction()||$actor<1||!in_array($action,['notifications.setup','notifications.email.configure','notifications.email.claim'],true))throw new LogicException('Notification audit requires its authorized mutation transaction.');
    query('INSERT INTO '.table('audit').' (user_id,action,detail,created_at) VALUES (?,?,?,?)',[$actor,$action,substr($detail,0,400),gmdate('Y-m-d H:i:s')]);
}
function notification_email_configure(bool $enabled):void {

nc_owner();$savedSettings=all('SELECT * FROM '.table('settings').' ORDER BY name');$auditError=null;
db()->exec("CREATE TRIGGER notifyci_fail_configure BEFORE INSERT ON notifyci_audit FOR EACH ROW BEGIN IF NEW.action='notifications.email.configure' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='synthetic configure failure'; END IF; END");
try{notification_email_configure(true);}catch(PDOException $e){$auditError=$e;}finally{db()->exec('DROP TRIGGER notifyci_fail_configure');}
nc_ok('Failed configuration audit cannot enable email', $auditError!==null&&str_contains($auditError->getMessage(),'synthetic configure failure')&&all('SELECT * FROM '.table('settings').' ORDER BY name')===$savedSettings&&!db()->inTransaction());
notification_email_configure(true);$queued=nc_emit('queued');
